class Solution:
    def mctFromLeafValues(self, arr):
        stack = []
        res = 0
        for x in arr:
            while stack and stack[-1] <= x:
                mid = stack.pop()
                res += mid * min(x, stack[-1] if stack else float('inf'))
            stack.append(x)
        while len(stack) > 1:
            res += stack.pop() * stack[-1]
        return res

