class Solution {
public:
    int mctFromLeafValues(vector<int>& arr) {
        vector<int> st;
        long long res = 0;
        for (int x : arr) {
            while (!st.empty() && st.back() <= x) {
                int mid = st.back(); st.pop_back();
                res += (long long)mid * (st.empty() ? INT_MAX : min(st.back(), x));
            }
            st.push_back(x);
        }
        while (st.size() > 1) {
            int mid = st.back(); st.pop_back();
            res += (long long)mid * st.back();
        }
        return (int)res;
    }
};

