class Solution {
    public int mctFromLeafValues(int[] arr) {
        Deque<Integer> st = new ArrayDeque<>();
        long res = 0;
        for (int x : arr) {
            while (!st.isEmpty() && st.peek() <= x) {
                int mid = st.pop();
                res += (long) mid * (st.isEmpty() ? Integer.MAX_VALUE : Math.min(st.peek(), x));
            }
            st.push(x);
        }
        while (st.size() > 1) res += (long) st.pop() * st.peek();
        return (int) res;
    }
}

